(** fuzz_headamp's compiled builder leaves pp_bytes at pp. For four inputs (the `role-master` seed W1, W7 with all
    three property kinds, W8 with a corruption, and T4 at every bound), each given after the harness's null and cap
    bytes [0; 0], the 19744 bytes the compiled code of LLVMFuzzerTestOneInput wrote at pp (the block of its first
    malloc), read at its second malloc call (plain 0x14048, UBSan 0x140e0) by running it in an RV64GC emulator, are
    written below as their non-zero runs. The plain and the UBSan image wrote the same bytes, and so did their
    pinned stripped twins (run at the same addresses: their PT_LOAD bytes differ only in the ELF header and the
    build-id note); a block filled with 0x00 and one filled with 0xa5 came out the same; the code read every input
    byte before that call. Images (sha256):
      unstripped plain fe40c856bfc73f2ba35a4cb6d434e65e1f675e72215e3ec4de3f810ed2858f12
      unstripped UBSan 1d123858383d3510bc9588bb43a84b3d5dfaa305ea7121e6d6650c82015c9878
      pinned plain     61497eebc35c52a0b5decd81ae453deeea1a18220ebf8f6436da6718b13c78b5
      pinned UBSan     0516fd55d25d0dc25addf9f7563673fa7a309e1f0c2e8c6a4bff0d6c9c8ef9e8
    Each lemma checks by computation that they are [pp_bytes] of the record [pod_build] makes of the input after
    the null and cap bytes, and that pod_build reads that input to its end, as the code did. A witness, at the
    real instance, that the Layout text is the memory the walk of the builder must reach. Statement text and
    computation only. *)
From Stdlib Require Import ZArith List Lia Bool.
From LinuxProcessSemantics.LinuxProcessSem Require Import BvBase.
From OSSVerify.Proofs.reac_pw.fuzz_headamp.lib.Pod Require Import Cursor Model Layout Sat.
Import ListNotations.
Open Scope Z_scope.

(** The byte list of length n with the runs (offset, bytes) and 0 elsewhere (runs in increasing order, disjoint). *)
Fixpoint expand_from (pos : Z) (n : nat) (runs : list (Z * list Z)) : list Z :=
  match runs with
  | [] => repeat 0 n
  | (o, bs) :: runs' =>
      repeat 0 (Z.to_nat (o - pos)) ++ bs ++
      expand_from (o + Z.of_nat (length bs)) (n - Z.to_nat (o - pos) - length bs) runs'
  end.
Definition expand (n : nat) (runs : list (Z * list Z)) : list Z := expand_from 0 n runs.

